43	inline std::size_t idx4(int b, int h, int s, int d, int heads, int seq_len, int head_dim)
44	{
45	    return (static_cast<std::size_t>(b) * static_cast<std::size_t>(heads) + static_cast<std::size_t>(h)) *
46	               static_cast<std::size_t>(seq_len) * static_cast<std::size_t>(head_dim) +
47	           static_cast<std::size_t>(s) * static_cast<std::size_t>(head_dim) + static_cast<std::size_t>(d);
