68	struct VerifyStats {
69	    float max_abs = 0.0f;
70	    float max_rel = 0.0f;
71	    float mean_abs = 0.0f;
72	    float rmse = 0.0f;
73	    std::size_t max_abs_idx = 0;
74	    std::size_t max_rel_idx = 0;
