78	
79	VerifyStats verify_allclose(
80	    const std::vector<float>& actual, const std::vector<float>& ref, float abs_tol, float rel_tol, float denom_eps)
81	{
82	    VerifyStats stats;
83	    if (actual.size() != ref.size() || actual.empty()) {
84	        stats.bad_count = std::max(actual.size(), ref.size());
85	        return stats;
86	    }
87	
88	    double sum_abs = 0.0;
89	    double sum_sq = 0.0;
90	    for (std::size_t i = 0; i < actual.size(); ++i) {
91	        const float a = actual[i];
92	        const float r = ref[i];
93	        if (!std::isfinite(a) || !std::isfinite(r)) {
94	            stats.has_nan_or_inf = true;
95	            ++stats.bad_count;
96	            continue;
97	        }
98	
99	        const float abs_diff = std::abs(a - r);
100	        const float denom = std::max(std::abs(r), denom_eps);
101	        const float rel_diff = abs_diff / denom;
102	
103	        sum_abs += static_cast<double>(abs_diff);
104	        sum_sq += static_cast<double>(abs_diff) * static_cast<double>(abs_diff);
105	
106	        if (abs_diff > stats.max_abs) {
107	            stats.max_abs = abs_diff;
108	            stats.max_abs_idx = i;
109	        }
110	        if (rel_diff > stats.max_rel) {
111	            stats.max_rel = rel_diff;
112	            stats.max_rel_idx = i;
113	        }
114	
115	        const float allowed = abs_tol + rel_tol * std::abs(r);
116	        if (!(abs_diff <= allowed)) {
117	            ++stats.bad_count;
118	        }
119	    }
120	
121	    const double n = static_cast<double>(actual.size());
122	    stats.mean_abs = static_cast<float>(sum_abs / n);
123	    stats.rmse = static_cast<float>(std::sqrt(sum_sq / n));
124	    return stats;
125	}
126	
127	void flash_attention_reference(
128	    const std::vector<float>& q, const std::vector<float>& k, const std::vector<float>& v, std::vector<float>& out,
129	    int batch, int heads, int seq_len, int head_dim, bool causal)
130	{
131	    const float scale = 1.0f / std::sqrt(static_cast<float>(head_dim));
132	
133	    for (int b = 0; b < batch; ++b) {
134	        for (int h = 0; h < heads; ++h) {
135	            for (int i = 0; i < seq_len; ++i) {
136	                const float* q_row = &q[idx4(b, h, i, 0, heads, seq_len, head_dim)];
137	
138	                const int j_limit = causal ? (i + 1) : seq_len;
139	                std::vector<float> scores(static_cast<std::size_t>(j_limit), 0.0f);
140	                float max_score = -std::numeric_limits<float>::infinity();
141	                for (int j = 0; j < j_limit; ++j) {
142	                    const float* k_row = &k[idx4(b, h, j, 0, heads, seq_len, head_dim)];
143	                    const float score = dot_qk(q_row, k_row, head_dim) * scale;
144	                    scores[static_cast<std::size_t>(j)] = score;
145	                    max_score = std::max(max_score, score);
146	                }
147	
148	                float denom = 0.0f;
149	                for (int j = 0; j < j_limit; ++j) {
150	                    scores[static_cast<std::size_t>(j)] = std::exp(scores[static_cast<std::size_t>(j)] - max_score);
151	                    denom += scores[static_cast<std::size_t>(j)];
152	                }
153	                const float inv_denom = (denom > 0.0f) ? (1.0f / denom) : 0.0f;
154	
155	                float* o_row = &out[idx4(b, h, i, 0, heads, seq_len, head_dim)];
156	                for (int d = 0; d < head_dim; ++d) {
157	                    o_row[d] = 0.0f;
158	                }
159	                for (int j = 0; j < j_limit; ++j) {
160	                    const float w = scores[static_cast<std::size_t>(j)] * inv_denom;
161	                    const float* v_row = &v[idx4(b, h, j, 0, heads, seq_len, head_dim)];
162	                    for (int d = 0; d < head_dim; ++d) {
163	                        o_row[d] += w * v_row[d];
164	                    }
165	                }
166	            }
167	        }
168	    }
169	}
170	
171	void flash_attention_pto(
172	    const std::vector<float>& q, const std::vector<float>& k, const std::vector<float>& v, std::vector<float>& out)
173	{
174	    constexpr int kB = kBatch;
175	    constexpr int kH = kHeads;
176	    constexpr int kS = kSeqLen;
177	    constexpr int kD = kHeadDim;
178	
179	    using GlobalQ = GlobalTensor<float, Shape<1, 1, 1, kS, kD>, Stride<kS * kD, kS * kD, kS * kD, kD, 1>>;
180	    using GlobalK = GlobalTensor<float, Shape<1, 1, 1, kS, kD>, Stride<kS * kD, kS * kD, kS * kD, kD, 1>>;
181	    using GlobalV = GlobalTensor<float, Shape<1, 1, 1, kS, kD>, Stride<kS * kD, kS * kD, kS * kD, kD, 1>>;
182	    using GlobalO = GlobalTensor<float, Shape<1, 1, 1, kS, kD>, Stride<kS * kD, kS * kD, kS * kD, kD, 1>>;
183	
184	    using QPlain = Tile<TileType::Vec, float, kS, kD, BLayout::RowMajor, kS, kD, SLayout::NoneBox>;
185	    using KPlain = Tile<TileType::Vec, float, kS, kD, BLayout::RowMajor, kS, kD, SLayout::NoneBox>;
186	    using KTPlain = Tile<TileType::Vec, float, kD, kS, BLayout::RowMajor, kD, kS, SLayout::NoneBox>;
187	    using VPlain = Tile<TileType::Vec, float, kS, kD, BLayout::RowMajor, kS, kD, SLayout::NoneBox>;
188	
189	    using ScoresPlain = Tile<TileType::Vec, float, kS, kS, BLayout::RowMajor, kS, kS, SLayout::NoneBox>;
190	    using RowReducePlain = Tile<TileType::Vec, float, kS, 1, BLayout::ColMajor, kS, 1, SLayout::NoneBox>;
191	
192	    using LeftQ = TileLeft<float, kS, kD, kS, kD>;
193	    using RightKT = TileRight<float, kD, kS, kD, kS>;
194	    using AccScores = TileAcc<float, kS, kS, kS, kS>;
195	
196	    using LeftP = TileLeft<float, kS, kS, kS, kS>;
197	    using RightV = TileRight<float, kS, kD, kS, kD>;
198	    using AccOut = TileAcc<float, kS, kD, kS, kD>;
199	
200	    const float scale = 1.0f / std::sqrt(static_cast<float>(kD));
201	
202	    for (int b = 0; b < kB; ++b) {
203	        for (int h = 0; h < kH; ++h) {
204	            const float* q_ptr = &q[idx4(b, h, 0, 0, kH, kS, kD)];
205	            const float* k_ptr = &k[idx4(b, h, 0, 0, kH, kS, kD)];
206	            const float* v_ptr = &v[idx4(b, h, 0, 0, kH, kS, kD)];
207	            float* o_ptr = &out[idx4(b, h, 0, 0, kH, kS, kD)];
208	
209	            GlobalQ qGlobal(const_cast<float*>(q_ptr));
210	            GlobalK kGlobal(const_cast<float*>(k_ptr));
211	            GlobalV vGlobal(const_cast<float*>(v_ptr));
212	            GlobalO oGlobal(o_ptr);
213	
214	            QPlain qTile;
215	            KPlain kTile;
216	            KTPlain ktTile;
217	            VPlain vTile;
218	
219	            LeftQ qLeft;
220	            RightKT kRight;
221	
222	            AccScores scoresAcc;
223	            ScoresPlain scores;
224	
225	            RowReducePlain rowMax;
226	            ScoresPlain scoresCentered;
227	            ScoresPlain expScores;
228	            RowReducePlain rowSum;
229	            ScoresPlain probs;
230	
231	            LeftP pLeft;
232	            RightV vRight;
233	            AccOut outAcc;
234	
235	            TLOAD(qTile, qGlobal);
236	            TLOAD(kTile, kGlobal);
237	            TLOAD(vTile, vGlobal);
238	
239	            TMOV(qLeft, qTile);
240	            TTRANS(ktTile, kTile, kTile);
241	            TMOV(kRight, ktTile);
242	
243	            TMATMUL(scoresAcc, qLeft, kRight);
244	            TMOV(scores, scoresAcc);
245	            TMULS(scores, scores, scale);
246	
247	            TROWMAX(rowMax, scores, scores);
248	            TROWEXPANDSUB(scoresCentered, scores, rowMax);
249	            TEXP(expScores, scoresCentered);
250	            TROWSUM(rowSum, expScores, expScores);
251	            TROWEXPANDDIV(probs, expScores, rowSum);
252	
253	            TMOV(pLeft, probs);
254	            TMOV(vRight, vTile);
255	            TMATMUL(outAcc, pLeft, vRight);
256	            TSTORE(oGlobal, outAcc);
257	        }
258	    }
259	}
260	
261	} // namespace
262	
263	int main(int argc, char** argv)
264	{
265	    const bool causal_requested = (argc >= 2) && (std::string(argv[1]) == "--causal");
266	    const bool causal = false;
267	    std::cout << "flash_attention_demo: B=" << kBatch << " H=" << kHeads << " S=" << kSeqLen << " D=" << kHeadDim
268	              << (causal_requested ? " (--causal ignored; non-causal only)\n" : " (non-causal)\n");
269	
270	    const std::size_t total = static_cast<std::size_t>(kBatch) * static_cast<std::size_t>(kHeads) *
271	                              static_cast<std::size_t>(kSeqLen) * static_cast<std::size_t>(kHeadDim);
272	    std::vector<float> q(total), k(total), v(total);
273	
274	    std::mt19937 rng(kRngSeed);
275	    std::normal_distribution<float> dist(0.0f, 1.0f);
276	    for (std::size_t i = 0; i < total; ++i) {
277	        q[i] = dist(rng) * kInitScale;
278	        k[i] = dist(rng) * kInitScale;
279	        v[i] = dist(rng) * kInitScale;
280	    }
281	
282	    std::vector<float> out_fused(total, 0.0f);
283	    std::vector<float> out_ref(total, 0.0f);
284	
285	    for (int i = 0; i < kWarmupIters; ++i) {
286	        flash_attention_pto(q, k, v, out_fused);
287	    }
288	    const auto t0 = std::chrono::steady_clock::now();
289	    for (int i = 0; i < kIters; ++i) {
290	        flash_attention_pto(q, k, v, out_fused);
291	    }
292	    const auto t1 = std::chrono::steady_clock::now();
293	    flash_attention_reference(q, k, v, out_ref, kBatch, kHeads, kSeqLen, kHeadDim, causal);
294	
295	    const double elapsed_s =
296	        std::chrono::duration_cast<std::chrono::duration<double>>(t1 - t0).count() / static_cast<double>(kIters);
297	    const double matmul_flops = 4.0 * static_cast<double>(kBatch) * static_cast<double>(kHeads) *
298	                                static_cast<double>(kSeqLen) * static_cast<double>(kSeqLen) *
299	                                static_cast<double>(kHeadDim);
300	    const double gflops = (elapsed_s > 0.0) ? (matmul_flops / elapsed_s / 1e9) : 0.0;
301	
